"""Spec: the two documented imports must both work, and `from app import ...`
must export everything plus a version string."""


def test_flask_current_app_import():
    from flask import current_app  # noqa: F401


def test_models_bulk_import():
    from app.models import (User, Role, Post, Comment, create_app, db, fake,
                            AnonymousUser, Permission, Follow)
    assert all(x is not None for x in (User, Role, Post, Comment, create_app,
                                       db, fake, AnonymousUser, Permission,
                                       Follow))


def test_app_bulk_import():
    from app import (User, Role, Post, Comment, create_app, db, fake,
                     AnonymousUser, Permission, Follow)
    assert all(x is not None for x in (User, Role, Post, Comment, create_app,
                                       db, fake, AnonymousUser, Permission,
                                       Follow))


def test_app_version_string():
    import app
    assert isinstance(app.__version__, str), app.__version__


def test_exceptions_module():
    from app.exceptions import ValidationError
    assert issubclass(ValidationError, Exception)

